<p>Private, structured assessments for <?= $kind==='casting'?'acting':'crew' ?> roles. Scores and recommendations never select an applicant, change public status or publish a character reveal.</p>
<section class="panel"><h2>Role-specific criteria</h2><?php foreach($view['roles'] as $role):?><p><a class="text-link" href="<?= e(p_url($kind,'evaluations',['role'=>$role['id']])) ?>"><?= e($role['title']) ?> — edit criteria</a></p><?php endforeach;?></section>
<?php if($view['role']):$role=$view['role'];$criteria=$view['criteria'];?>
<section class="panel"><h2><?= e($role['title']) ?> — assessment criteria</h2><p>All scores use a 0–10 scale. Leave weight at 1 for equal weighting. Publish a version after saving; changing a draft does not alter earlier scores.</p><form method="post" action="<?= e(p_url($kind,'evaluations')) ?>"><?php p_csrf();p_hidden('action','rubric_save');p_hidden('role_id',$role['id']);?>
<?php foreach([...$criteria,['id'=>'c'.bin2hex(random_bytes(5))],['id'=>'c'.bin2hex(random_bytes(5))],['id'=>'c'.bin2hex(random_bytes(5))]] as $index=>$criterion):$key=$criterion['id'];?><fieldset class="question"><legend>Criterion <?= $index+1 ?></legend><?php p_hidden('criteria['.$key.'][id]',$key);?><label for="criterion_<?= e($key) ?>">Name (leave blank to skip)</label><input id="criterion_<?= e($key) ?>" name="criteria[<?= e($key) ?>][label]" maxlength="120" value="<?= e($criterion['label']??'') ?>"><label for="weight_<?= e($key) ?>">Weight</label><input id="weight_<?= e($key) ?>" name="criteria[<?= e($key) ?>][weight]" type="number" min="0.01" max="100" step="0.01" value="<?= e((string)($criterion['weight']??1)) ?>"><label for="order_<?= e($key) ?>">Order</label><input id="order_<?= e($key) ?>" name="criteria[<?= e($key) ?>][order]" type="number" min="0" max="999" value="<?= (int)($criterion['order']??($index+1)*10) ?>"><label class="check"><input name="criteria[<?= e($key) ?>][remove]" type="checkbox" value="1"> Remove this criterion when saving</label></fieldset><?php endforeach;?><button class="button">Save assessment draft</button></form>
<form method="post" action="<?= e(p_url($kind,'evaluations')) ?>"><?php p_csrf();p_hidden('action','rubric_publish');p_hidden('role_id',$role['id']);?><button class="button">Publish a new assessment version</button></form><h3>Version history</h3><?php foreach($view['versions'] as $version):?><p>Version <?= (int)$version['version'] ?> · <?= e($version['published_at']) ?> UTC</p><?php endforeach;?></section><?php endif;?>
<section class="panel"><h2>Applicants</h2><?php foreach($view['applications'] as $app):?><p><a class="text-link" href="<?= e(p_url($kind,'evaluations',['application'=>$app['id']])) ?>"><?= e($app['full_name'].' · '.$app['title'].' · '.$app['reference']) ?></a></p><?php endforeach;?></section>
<?php if($view['application']):$app=$view['application'];$previous=$view['own_previous'];$oldScores=$previous&&(int)$previous['rubric_version']===(int)$view['score_version']?json_decode($previous['scores_json'],true):[];?>
<section class="panel"><h2><?= e($app['full_name']) ?></h2><p><?= e($app['role_title'].' · '.$app['reference']) ?></p><a class="text-link" href="<?= e(admin_url($kind).'&application='.$app['id']) ?>">Open recruitment review / final decision →</a>
<?php if(!$view['score_schema']):?><p>Publish assessment criteria for this role before scoring.</p><a class="text-link" href="<?= e(p_url($kind,'evaluations',['role'=>$app['role_id']])) ?>">Configure this role’s criteria →</a><?php else:?>
<p>Published criteria version <?= (int)$view['score_version'] ?>. <?= $previous?'Saving creates a new revision of your own review and preserves its history.':'This will be your first review of this application.' ?></p><form method="post" action="<?= e(p_url($kind,'evaluations')) ?>"><?php p_csrf();p_hidden('action','evaluation_save');p_hidden('application_id',$app['id']);p_hidden('rubric_version',$view['score_version']);p_hidden('supersedes_id',$previous['id']??0);?>
<?php foreach($view['score_schema'] as $criterion):?><label for="score_<?= e($criterion['id']) ?>"><?= e($criterion['label']) ?> — weight <?= e((string)$criterion['weight']) ?></label><input id="score_<?= e($criterion['id']) ?>" name="scores[<?= e($criterion['id']) ?>]" type="number" min="0" max="10" step="0.01" value="<?= e((string)($oldScores[$criterion['id']]??'')) ?>" required><?php endforeach;?>
<label for="recommendation">Private recommendation</label><select id="recommendation" name="recommendation"><?php foreach(P_RECOMMENDATIONS as $value=>$label):?><option value="<?= e($value) ?>"<?= ($previous['recommendation']??'hold')===$value?' selected':'' ?>><?= e($label) ?></option><?php endforeach;?></select><label for="private_feedback">Private written feedback (optional)</label><textarea id="private_feedback" name="private_feedback" maxlength="4000" rows="5"><?= e($previous['private_feedback']??'') ?></textarea><p class="field-help">Feedback is not sent to applicants. Final selection remains a separate, authorized recruitment action.</p><button class="button">Save private evaluation</button></form><?php endif;?></section>
<section class="panel"><h2>Evaluation history</h2><?php foreach($view['reviews'] as $review):$schema=json_decode($review['schema_json'],true);$scores=json_decode($review['scores_json'],true);?><article class="booking"><h3><?= e($review['reviewer_name']) ?> · Revision <?= (int)$review['revision'] ?></h3><p><?= e($review['created_at']) ?> UTC · Criteria v<?= (int)$review['rubric_version'] ?></p><p>Weighted score: <?= e($review['weighted_score']) ?> / 10 · Recommendation: <?= e(P_RECOMMENDATIONS[$review['recommendation']]) ?></p><dl><?php foreach($schema as $criterion):?><dt><?= e($criterion['label']) ?> (weight <?= e((string)$criterion['weight']) ?>)</dt><dd><?= e((string)($scores[$criterion['id']]??'')) ?> / 10</dd><?php endforeach;?></dl><p><?= nl2br(e($review['private_feedback'])) ?></p><?php if($review['supersedes_id']):?><p class="field-help">Revises review #<?= (int)$review['supersedes_id'] ?>. Earlier records remain in this history.</p><?php endif;?></article><?php endforeach;?></section><?php endif;?>
